import { Task } from "../domain/task";
import { TaskStatus } from "../domain/task-status";

export interface CreateUserDto { name: string; }
export interface CreateProjectDto { name: string; }
export interface CreateTaskDto {
  projectId: string;
  title: string;
  description?: string;
  dueDate?: string;
  status?: string;
}
export interface AssignTaskDto { taskId: string; assigneeId: string; }
export interface ListTasksDto { projectId: string; status?: string; assigneeId?: string; }

export interface TaskResponseDto {
  id: string;
  projectId: string;
  title: string;
  description: string;
  dueDate: string | null;
  status: TaskStatus;
  assigneeId: string | null;
}

export function toTaskResponse(task: Task): TaskResponseDto {
  return {
    id: task.id,
    projectId: task.projectId,
    title: task.title,
    description: task.description,
    dueDate: task.dueDate ? task.dueDate.toISOString() : null,
    status: task.status,
    assigneeId: task.assigneeId ?? null,
  };
}

